private val repoJson = Json { ignoreUnknownKeys = true; explicitNulls = false }
private fun Throwable.toDomain(): DomainError = when (this) { is HttpApiException -> when (statusCode) { 401 -> DomainError.Authentication("Authentication failed"); 403 -> DomainError.Permission("Permission denied"); 404 -> DomainError.NotFound("remote", statusCode.toString()); 409 -> DomainError.Conflict("Remote conflict"); 422 -> DomainError.Validation("Validation failed"); 429 -> DomainError.RateLimited("Rate limited"); in 500..599 -> DomainError.Server("Server error"); else -> DomainError.Unknown("HTTP $statusCode") }; else -> DomainError.Network(message ?: "Network failure") }
private fun Throwable?.isRetryableHttp() = this is HttpApiException && statusCode in 408..599
@Serializable private data class AttributeWrite(val name:String,val slug:String)
@Serializable private data class TermWrite(val name:String,val slug:String)
@Serializable private data class NoteWrite(val note:String,val customer_note:Boolean)
private const val OP_MARKER_START = '\u2063'
private const val OP_MARKER_END = '\u2064'
private const val OP_BIT_ZERO = '\u200B'
private const val OP_BIT_ONE = '\u200C'
private fun operationMarker(operationId:String):String = buildString { append(OP_MARKER_START); operationId.toByteArray(Charsets.UTF_8).forEach { byte -> for (bit in 7 downTo 0) append(if (((byte.toInt() shr bit) and 1) == 0) OP_BIT_ZERO else OP_BIT_ONE) }; append(OP_MARKER_END) }
private fun stripOperationMarker(note:String):String = note.substringBefore(OP_MARKER_START).trimEnd()
private fun hasOperationMarker(note:String,operationId:String)=note.contains(operationMarker(operationId))
private fun metaOperationId(items:List<WooMetaDataDto>,operationId:String)=items.any{it.key=="_woogit_operation_id"&&it.value is JsonPrimitive&&it.value.contentOrNull==operationId}

class VariationRepositoryImpl(private val local:LocalVariationDataSource,private val provider:WooCommerceClientProvider,private val coordinator:MutationCoordinator,private val pending:PendingOperationRepository):VariationRepository {
 override suspend fun list(storeId:StoreId,productId:EntityId,page:Int,perPage:Int)=if(page==1) local.list(storeId,productId).fold({cached->if(cached.isNotEmpty())CoreResult.Success(cached)else fetchList(storeId,productId,page,perPage)},{fetchList(storeId,productId,page,perPage)}) else fetchList(storeId,productId,page,perPage)
 private suspend fun fetchList(storeId:StoreId,productId:EntityId,page:Int,perPage:Int)=provider.client(storeId).fold({(store,api)->api.variations(store.baseUrl,productId.value.toLong(),page,perPage).fold({items->val values=items.map{it.toDomain(productId)};values.forEach{local.upsert(storeId,it)};CoreResult.Success(values)},{if(page==1)local.list(storeId,productId)else CoreResult.Failure(it.toDomain())})},{if(page==1)local.list(storeId,productId)else CoreResult.Failure(it)})
 override suspend fun get(storeId:StoreId,productId:EntityId,id:EntityId)=local.get(storeId,productId,id).fold({cached->CoreResult.Success(cached)},{provider.client(storeId).fold({(store,api)->api.variation(store.baseUrl,productId.value.toLong(),id.value.toLong()).fold({remote->val value=remote.toDomain(productId);local.upsert(storeId,value);CoreResult.Success(value)},{local.get(storeId,productId,id)})},{local.get(storeId,productId,id)})})
 override suspend fun create(storeId:StoreId,value:Variation)=mutate(storeId,value,OperationType.CREATE){api,store,operationId->val existing=api.variations(store.baseUrl,value.productId.value.toLong(),1,100).getOrThrow().firstOrNull{metaOperationId(it.meta_data,operationId)};existing?.let{Result.success(it)}?:api.createVariation(store.baseUrl,value.productId.value.toLong(),value.toDto(operationId))}
 override suspend fun update(storeId:StoreId,productId:EntityId,id:EntityId,value:Variation)=mutate(storeId,value,OperationType.UPDATE){api,store,_->api.updateVariation(store.baseUrl,productId.value.toLong(),id.value.toLong(),value.toDto())}
 override suspend fun delete(storeId:StoreId,productId:EntityId,id:EntityId):CoreResult<Unit>{val op=PendingOperation(EntityId("variation-delete-${storeId.value}-${productId.value}-${id.value}"),storeId,"variation",id,OperationType.DELETE,"{}",id.value,0,null,null);val localResult=coordinator.execute(op){local.delete(storeId,productId,id)};if(localResult is CoreResult.Failure)return localResult;return provider.client(storeId).fold({(store,api)->api.deleteVariation(store.baseUrl,productId.value.toLong(),id.value.toLong()).fold({pending.markSucceeded(op.id);CoreResult.Success(Unit)},{e->if(e.isRetryableHttp())CoreResult.Success(Unit)else CoreResult.Failure(e.toDomain())})},{e->if(e.recoverable)CoreResult.Success(Unit)else CoreResult.Failure(e)})}
 private suspend fun mutate(storeId:StoreId,value:Variation,type:OperationType,remote:suspend(TypedWooCommerceApi,StoreConnection,String)->Result<WooVariationTypedDto>):CoreResult<Variation>{val payload=repoJson.encodeToString(value.toDto());val op=PendingOperation(EntityId("variation-${type.name.lowercase()}-${storeId.value}-${value.productId.value}-${value.id.value}"),storeId,"variation",value.id,type,payload,payload.hashCode().toString(),0,null,null);val localResult=coordinator.execute(op){local.upsert(storeId,value)};if(localResult is CoreResult.Failure)return localResult;return provider.client(storeId).fold({(store,api)->remote(api,store,op.id.value).fold({raw->val d=raw.toDomain(value.productId);local.upsert(storeId,d);pending.markSucceeded(op.id);CoreResult.Success(d)},{e->if(e.isRetryableHttp())CoreResult.Success(value)else CoreResult.Failure(e.toDomain())})},{e->if(e.recoverable)CoreResult.Success(value)else CoreResult.Failure(e)})}
}
private fun WooVariationTypedDto.toDomain(productId:EntityId)=Variation(EntityId(id.toString()),productId,attributes.map{VariationAttribute(it.name,it.option)},Pricing(regular_price,sale_price,sale_price!=null),Stock(stock_quantity,when(stock_status){"outofstock"->StockStatus.OUT_OF_STOCK;"onbackorder"->StockStatus.ON_BACKORDER;else->StockStatus.IN_STOCK},manage_stock),sku,image?.let{ProductImage(it.id?.let{v->EntityId(v.toString())},it.src.orEmpty(),it.name,it.alt)},date_modified_gmt?.let{runCatching{Instant.parse(it)}.getOrNull()})

private fun Variation.toDto(operationId:String?=null): WooVariationTypedDto {
    val regular = pricing.regular?.trim()?.takeIf { it.isNotBlank() }
    val sale = pricing.sale?.trim()?.takeIf { it.isNotBlank() && it != regular }
    val stockStatus = when (stock?.status) { StockStatus.OUT_OF_STOCK -> "outofstock"; StockStatus.ON_BACKORDER -> "onbackorder"; StockStatus.IN_STOCK, null -> "instock" }
    return WooVariationTypedDto(id=id.value.toLongOrNull()?:0L,product_id=productId.value.toLongOrNull()?:0L,sku=sku?.trim()?.takeIf{it.isNotBlank()},regular_price=regular,sale_price=sale,price=sale?:regular,stock_quantity=stock?.quantity,stock_status=stockStatus,manage_stock=stock?.manageStock?:false,image=image?.let{WooImageTypedDto(it.id?.value?.toLongOrNull(),it.src,it.name,it.alt)},date_modified_gmt=modifiedAt?.toString(),attributes=attributes.filter{it.name.isNotBlank()&&it.option.isNotBlank()}.map{WooVariationAttributeDto(null,it.name.trim(),it.option.trim())},meta_data=operationId?.let{listOf(WooMetaDataDto(key="_woogit_operation_id",value=JsonPrimitive(it)))}?:emptyList())
}

class AttributeRepositoryImpl(private val local:LocalAttributeDataSource,private val provider:WooCommerceClientProvider,private val coordinator:MutationCoordinator,private val pending:PendingOperationRepository):AttributeRepository{
 override suspend fun list(storeId:StoreId,page:Int,perPage:Int)=if(page==1)local.list(storeId).fold({cached->if(cached.isNotEmpty())CoreResult.Success(cached)else fetchList(storeId,page,perPage)},{fetchList(storeId,page,perPage)}) else fetchList(storeId,page,perPage)
 private suspend fun fetchList(storeId:StoreId,page:Int,perPage:Int)=provider.client(storeId).fold({(store,api)->api.attributes(store.baseUrl,page,perPage).fold({items->val values=items.map{it.toDomain()};values.forEach{local.upsert(storeId,it)};CoreResult.Success(values)},{if(page==1)local.list(storeId)else CoreResult.Failure(it.toDomain())})},{if(page==1)local.list(storeId)else CoreResult.Failure(it)})
 override suspend fun get(storeId:StoreId,id:EntityId)=local.get(storeId,id).fold({cached->CoreResult.Success(cached)},{provider.client(storeId).fold({(store,api)->api.attribute(store.baseUrl,id.value.toLong()).fold({v->val d=v.toDomain();local.upsert(storeId,d);CoreResult.Success(d)},{local.get(storeId,id)})},{local.get(storeId,id)})})
 override suspend fun create(storeId:StoreId,value:GlobalAttribute)=mutate(storeId,value,OperationType.CREATE){api,store,_->api.createAttribute(store.baseUrl,value.toDto())}
 override suspend fun update(storeId:StoreId,id:EntityId,value:GlobalAttribute)=mutate(storeId,value,OperationType.UPDATE){api,store,_->api.updateAttribute(store.baseUrl,id.value.toLong(),value.toDto())}
 override suspend fun delete(storeId:StoreId,id:EntityId):CoreResult<Unit>{val op=PendingOperation(EntityId("attribute-delete-${storeId.value}-${id.value}"),storeId,"attribute",id,OperationType.DELETE,"{}",id.value,0,null,null);val localResult=coordinator.execute(op){local.delete(storeId,id)};if(localResult is CoreResult.Failure)return localResult;return provider.client(storeId).fold({(store,api)->api.deleteAttribute(store.baseUrl,id.value.toLong()).fold({pending.markSucceeded(op.id);CoreResult.Success(Unit)},{e->if(e.isRetryableHttp())CoreResult.Success(Unit)else CoreResult.Failure(e.toDomain())})},{e->if(e.recoverable)CoreResult.Success(Unit)else CoreResult.Failure(e)})}
 private suspend fun mutate(storeId:StoreId,value:GlobalAttribute,type:OperationType,remote:suspend(TypedWooCommerceApi,StoreConnection,String)->Result<WooGlobalAttributeDto>):CoreResult<GlobalAttribute>{val payload=repoJson.encodeToString(value.toDto());val op=PendingOperation(EntityId("attribute-${type.name.lowercase()}-${storeId.value}-${value.id.value}"),storeId,"attribute",value.id,type,payload,payload.hashCode().toString(),0,null,null);val localResult=coordinator.execute(op){local.upsert(storeId,value)};if(localResult is CoreResult.Failure)return localResult;return provider.client(storeId).fold({(store,api)->val result=if(type==OperationType.CREATE){val existing=api.attributes(store.baseUrl,1,100).getOrThrow().firstOrNull{it.slug.equals(value.slug,true)&&it.name.equals(value.name,true)};existing?.let{Result.success(it)}?:remote(api,store,op.id.value)}else remote(api,store,op.id.value);result.fold({raw->val d=raw.toDomain();local.upsert(storeId,d);pending.markSucceeded(op.id);CoreResult.Success(d)},{e->if(e.isRetryableHttp())CoreResult.Success(value)else CoreResult.Failure(e.toDomain())})},{e->if(e.recoverable)CoreResult.Success(value)else CoreResult.Failure(e)})}
}
private fun WooGlobalAttributeDto.toDomain()=GlobalAttribute(EntityId(id.toString()),name,slug,emptyList())
private fun GlobalAttribute.toDto()=WooGlobalAttributeDto(id.value.toLongOrNull()?:0L,name,slug)

class TermRepositoryImpl(private val local:LocalTermDataSource,private val provider:WooCommerceClientProvider,private val coordinator:MutationCoordinator,private val pending:PendingOperationRepository):TermRepository{
 override suspend fun list(storeId:StoreId,attributeId:EntityId,page:Int,perPage:Int)=if(page==1)local.list(storeId,attributeId).fold({cached->if(cached.isNotEmpty())CoreResult.Success(cached)else fetchList(storeId,attributeId,page,perPage)},{fetchList(storeId,attributeId,page,perPage)}) else fetchList(storeId,attributeId,page,perPage)
 private suspend fun fetchList(storeId:StoreId,attributeId:EntityId,page:Int,perPage:Int)=provider.client(storeId).fold({(store,api)->api.terms(store.baseUrl,attributeId.value.toLong(),page,perPage).fold({items->val values=items.map{it.toDomain()};values.forEach{local.upsert(storeId,attributeId,it)};CoreResult.Success(values)},{if(page==1)local.list(storeId,attributeId)else CoreResult.Failure(it.toDomain())})},{if(page==1)local.list(storeId,attributeId)else CoreResult.Failure(it)})
 override suspend fun get(storeId:StoreId,attributeId:EntityId,id:EntityId)=local.list(storeId,attributeId).fold({items->items.firstOrNull{it.id==id}?.let{CoreResult.Success(it)}?:fetchGet(storeId,attributeId,id)},{fetchGet(storeId,attributeId,id)})
 private suspend fun fetchGet(storeId:StoreId,attributeId:EntityId,id:EntityId)=provider.client(storeId).fold({(store,api)->api.term(store.baseUrl,attributeId.value.toLong(),id.value.toLong()).fold({v->val d=v.toDomain();local.upsert(storeId,attributeId,d);CoreResult.Success(d)},{CoreResult.Failure(it.toDomain())})},{CoreResult.Failure(it)})
 override suspend fun create(storeId:StoreId,attributeId:EntityId,value:AttributeTerm)=mutate(storeId,attributeId,value,OperationType.CREATE){api,store,_->api.createTerm(store.baseUrl,attributeId.value.toLong(),value.toDto())}
 override suspend fun update(storeId:StoreId,attributeId:EntityId,id:EntityId,value:AttributeTerm)=mutate(storeId,attributeId,value,OperationType.UPDATE){api,store,_->api.updateTerm(store.baseUrl,attributeId.value.toLong(),id.value.toLong(),value.toDto())}
 override suspend fun delete(storeId:StoreId,attributeId:EntityId,id:EntityId):CoreResult<Unit>{val op=PendingOperation(EntityId("term-delete-${storeId.value}-${attributeId.value}-${id.value}"),storeId,"term",id,OperationType.DELETE,"{}",id.value,0,null,null);val localResult=coordinator.execute(op){local.delete(storeId,attributeId,id)};if(localResult is CoreResult.Failure)return localResult;return provider.client(storeId).fold({(store,api)->api.deleteTerm(store.baseUrl,attributeId.value.toLong(),id.value.toLong()).fold({pending.markSucceeded(op.id);CoreResult.Success(Unit)},{e->if(e.isRetryableHttp())CoreResult.Success(Unit)else CoreResult.Failure(e.toDomain())})},{e->if(e.recoverable)CoreResult.Success(Unit)else CoreResult.Failure(e)})}
 private suspend fun mutate(storeId:StoreId,attributeId:EntityId,value:AttributeTerm,type:OperationType,remote:suspend(TypedWooCommerceApi,StoreConnection,String)->Result<WooAttributeTermDto>):CoreResult<AttributeTerm>{val payload=repoJson.encodeToString(value.toDto());val id=value.id?:EntityId("local-${attributeId.value}-${value.name.hashCode()}");val op=PendingOperation(EntityId("term-${type.name.lowercase()}-${storeId.value}-${id.value}"),storeId,"term",id,type,payload,payload.hashCode().toString(),0,null,null);val localResult=coordinator.execute(op){local.upsert(storeId,attributeId,value)};if(localResult is CoreResult.Failure)return localResult;return provider.client(storeId).fold({(store,api)->val result=if(type==OperationType.CREATE){val existing=api.terms(store.baseUrl,attributeId.value.toLong(),1,100).getOrThrow().firstOrNull{it.slug.equals(value.slug ?: "",true)&&it.name.equals(value.name,true)};existing?.let{Result.success(it)}?:remote(api,store,op.id.value)}else remote(api,store,op.id.value);result.fold({raw->val d=raw.toDomain();local.upsert(storeId,attributeId,d);pending.markSucceeded(op.id);CoreResult.Success(d)},{e->if(e.isRetryableHttp())CoreResult.Success(value)else CoreResult.Failure(e.toDomain())})},{e->if(e.recoverable)CoreResult.Success(value)else CoreResult.Failure(e)})}
}
private fun WooAttributeTermDto.toDomain()=AttributeTerm(EntityId(id.toString()),name,slug)
private fun AttributeTerm.toDto()=WooAttributeTermDto(id?.value?.toLongOrNull()?:0L,name,slug ?: "")

class OrderNoteRepositoryImpl(private val provider:WooCommerceClientProvider,private val pending:PendingOperationRepository):OrderNoteRepository{
 override suspend fun addNote(storeId:StoreId,orderId:EntityId,content:String,customerNote:Boolean):CoreResult<OrderNote>{val payload=repoJson.encodeToString(NoteWrite(content,customerNote));val op=PendingOperation(EntityId("order-note-${storeId.value}-${orderId.value}-${payload.hashCode()}"),storeId,"order_note",orderId,OperationType.CREATE,payload,payload.hashCode().toString(),0,null,null);pending.enqueue(op);return provider.client(storeId).fold({(store,api)->val marker=operationMarker(op.id.value);val existing=api.orderNotes(store.baseUrl,orderId.value.toLong()).getOrThrow().firstOrNull{hasOperationMarker(it.note,op.id.value)};val result=existing?.let{Result.success(it)}?:api.addOrderNote(store.baseUrl,orderId.value.toLong(),WooOrderNoteDto(note=content+marker,customer_note=customerNote));result.fold({note->pending.markSucceeded(op.id);CoreResult.Success(OrderNote(EntityId(note.id.toString()),stripOperationMarker(note.note),note.customer_note))},{e->if(e.isRetryableHttp())CoreResult.Success(OrderNote(null,content,customerNote))else CoreResult.Failure(e.toDomain())})},{e->if(e.recoverable)CoreResult.Success(OrderNote(null,content,customerNote))else CoreResult.Failure(e)})}
}
